"""Adjusts the block for the proper timing interval"""
def timeBlock(block: Any, dur: Any) -> object {
    nBlock = [];
    for (i, b) in enumerate(block) {
        if (i == 0) {
            nBlock.append(b);
        } else {
            j = i - 1;
            prev = block[j];
            ev = b + dur + prev;
            nBlock.append(ev);
        }
    }
    return nBlock;
}

